//! Randomness parity with the reference.
//!
//! The corpus in `corpus/rng/engine.csv` is generated by
//! `oracle/probes/rng_corpus.cpp`, which uses the same standard library the
//! reference is built with: the reference draws from `std::minstd_rand0`
//! (`src/rng.h:30`) through default-constructed distributions (`src/rng.cpp:16`).
//! Because those distributions are implementation-defined, the corpus — not the
//! standard's description — is the specification.

// Tests fail by panicking; the workspace denies `expect_used`/`panic` to keep
// library code total, not to change how a failing test reports itself.
#![allow(clippy::expect_used, clippy::panic)]

use std::collections::HashMap;
use std::path::PathBuf;

use cdda_core_types::rng::{MinStdRand0, NormalDistribution};

/// Case name, seed, and the expected draws as written in the corpus.
fn corpus() -> HashMap<String, Vec<(u32, Vec<String>)>> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../corpus/rng/engine.csv");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("reading {}: {e}", path.display()));
    let mut out: HashMap<String, Vec<(u32, Vec<String>)>> = HashMap::new();
    for line in text.lines() {
        if line.starts_with('#') || line.trim().is_empty() {
            continue;
        }
        let mut fields = line.split(',');
        let case = fields.next().expect("case").to_owned();
        let seed: u32 = fields.next().expect("seed").parse().expect("seed number");
        let draws = fields.map(str::to_owned).collect();
        out.entry(case).or_default().push((seed, draws));
    }
    out
}

#[test]
fn engine_stream_matches_the_reference() {
    let corpus = corpus();
    let cases = corpus.get("engine_raw").expect("engine_raw cases");
    assert!(!cases.is_empty(), "corpus has no engine cases");
    for (seed, expected) in cases {
        let mut engine = MinStdRand0::seeded(*seed);
        for (index, want) in expected.iter().enumerate() {
            let got = engine.next_u32().to_string();
            assert_eq!(&got, want, "seed {seed}, draw {index}");
        }
    }
}

#[test]
fn uniform_int_matches_the_reference() {
    let corpus = corpus();
    let cases = corpus
        .get("uniform_int_-10_10")
        .expect("uniform_int_-10_10 cases");
    assert!(!cases.is_empty(), "corpus has no uniform_int cases");
    for (seed, expected) in cases {
        let mut engine = MinStdRand0::seeded(*seed);
        for (index, want) in expected.iter().enumerate() {
            let got = engine.uniform_int(-10, 10);
            let want: i32 = want.parse().expect("uniform_int draw");
            assert_eq!(got, want, "seed {seed}, draw {index}");
        }
    }
}

#[test]
fn uniform_uint_full_range_matches_the_reference() {
    let corpus = corpus();
    let cases = corpus
        .get("uniform_uint_full")
        .expect("uniform_uint_full cases");
    assert!(!cases.is_empty(), "corpus has no uniform_uint cases");
    for (seed, expected) in cases {
        let mut engine = MinStdRand0::seeded(*seed);
        for (index, want) in expected.iter().enumerate() {
            let got = engine.uniform_uint();
            let want: u32 = want.parse().expect("uniform_uint draw");
            assert_eq!(got, want, "seed {seed}, draw {index}");
        }
    }
}

#[test]
fn uniform_real_matches_the_reference() {
    let corpus = corpus();
    let cases = corpus
        .get("uniform_real_0_1")
        .expect("uniform_real_0_1 cases");
    assert!(!cases.is_empty(), "corpus has no uniform_real cases");
    for (seed, expected) in cases {
        let mut engine = MinStdRand0::seeded(*seed);
        for (index, want) in expected.iter().enumerate() {
            let got = engine.uniform_real();
            let want: f64 = want.parse().expect("uniform_real draw");
            assert_eq!(
                got.to_bits(),
                want.to_bits(),
                "seed {seed}, draw {index}: got {got:?}, want {want:?}"
            );
        }
    }
}

#[test]
fn normal_matches_the_reference() {
    let corpus = corpus();
    let cases = corpus.get("normal_0_1").expect("normal_0_1 cases");
    assert!(!cases.is_empty(), "corpus has no normal cases");
    for (seed, expected) in cases {
        let mut engine = MinStdRand0::seeded(*seed);
        let mut normal = NormalDistribution::standard();
        for (index, want) in expected.iter().enumerate() {
            let got = normal.next(&mut engine);
            let want: f64 = want.parse().expect("normal draw");
            assert_eq!(
                got.to_bits(),
                want.to_bits(),
                "seed {seed}, draw {index}: got {got:?}, want {want:?}"
            );
        }
    }
}
